-- Clear Talks CT-02g — STAGED ONLY (no hosted SQL applied).
-- Name generated by Supabase CLI v3.2.0, isolated GitHub Actions 45298277039.
-- Requires CT-02b/c/e/f in that order, verified backup, approved owner/grants,
-- complete API/reader image test and explicit production release approval.
begin;

-- Public metadata must NEVER be read from the editorial base table. Existing
-- public media bucket object URLs are left untouched for article compatibility.
-- Intentional tightly scoped owner-rights view: this view is a projection with
-- a fixed column whitelist and a security barrier, not a general RLS bypass.
-- Only approved, nonembargoed, nonexpired, nonsuperseded media are projected.
-- SECURITY NOTE: A view uses its owner's table privileges by default; this
-- exception is subject to explicit security review and publisher QA.
create view public.media_public_assets with (security_barrier = true) as
select
  m.id,
  m.url,
  m.alt_text,
  m.caption,
  m.credit,
  m.width,
  m.height,
  m.display_caption,
  m.display_credit,
  m.decorative
from public.media_assets m
where m.status = 'approved'
  and (m.embargo_until is null or m.embargo_until <= now())
  and (m.license_expires_at is null or m.license_expires_at > now())
  and m.is_superseded = false
  and m.trashed_at is null;

revoke all on public.media_public_assets from public, anon, authenticated;
grant select on public.media_public_assets to anon, authenticated;

-- A public view returns a finite safe projection. The editorial base table
-- must not remain directly readable by anonymous callers, nor by readers
-- who merely carry an authenticated JWT.
drop policy if exists media_select_public on public.media_assets;
drop policy if exists media_insert_staff on public.media_assets;
drop policy if exists media_update_staff on public.media_assets;
drop policy if exists media_delete_staff on public.media_assets;

revoke select on public.media_assets from anon;
-- Existing authenticated table grants remain, but staff RLS always filters.
create policy ct02g_media_select_staff
on public.media_assets for select to authenticated using (
  newsroom_private.has_staff_permission('media.view_all',null,uploaded_by)
  or newsroom_private.has_staff_permission('media.edit_all',null,uploaded_by)
  or newsroom_private.has_staff_permission('media.edit_own',null,uploaded_by)
);

create policy ct02g_media_insert_staff
on public.media_assets for insert to authenticated with check (
  newsroom_private.has_staff_permission('media.upload')
  and uploaded_by = (select auth.uid())
  and status = 'draft'
  and approved_by is null
  and approved_at is null
  and trashed_at is null
  and exists(
    select 1 from storage.objects o
    where o.bucket_id = 'media' and o.name = storage_path
      and o.owner_id = (select auth.uid())::text
  )
);

create policy ct02g_media_update_staff
on public.media_assets for update to authenticated using (
  newsroom_private.has_staff_permission('media.edit_all',null,uploaded_by)
  or newsroom_private.has_staff_permission('media.edit_own',null,uploaded_by)
) with check (
  newsroom_private.has_staff_permission('media.edit_all',null,uploaded_by)
  or newsroom_private.has_staff_permission('media.edit_own',null,uploaded_by)
);

create policy ct02g_media_delete_staff
on public.media_assets for delete to authenticated using (
  newsroom_private.has_staff_permission('media.delete',null,uploaded_by)
);

-- Per-column transition checks defend direct PostgREST UPDATE even when the
-- user has broad edit rights. The original file path and uploader identity
-- are immutable; approval, archiving, trashing require separate privileges.
create function newsroom_private.guard_media_asset_write()
returns trigger language plpgsql security invoker set search_path = ''
as $fn$
begin
  if current_user <> 'authenticated' then return new; end if;

  if tg_op = 'INSERT' then
    if new.uploaded_by is distinct from (select auth.uid())
      or new.status <> 'draft'
      or new.approved_at is not null
      or new.approved_by is not null then
      raise exception 'Media upload must start as a draft owned by caller'
        using errcode = '42501';
    end if;
    return new;
  end if;

  if new.id is distinct from old.id
    or new.uploaded_by is distinct from old.uploaded_by
    or new.storage_path is distinct from old.storage_path
    or new.url is distinct from old.url
    or new.created_at is distinct from old.created_at then
    raise exception 'Media source and upload identity are immutable'
      using errcode = '42501';
  end if;

  if new.status is distinct from old.status then
    if new.status = 'approved' and not
      newsroom_private.has_staff_permission('media.approve',null,old.uploaded_by)
    then
      raise exception 'Media approval requires a separate grant'
        using errcode = '42501';
    end if;
    if new.status in ('archived','trashed') and not
      newsroom_private.has_staff_permission('media.delete',null,old.uploaded_by)
    then
      raise exception 'Media archival and trash require a separate grant'
        using errcode = '42501';
    end if;
    if new.status = 'restricted' and not
      newsroom_private.has_staff_permission('media.approve',null,old.uploaded_by)
    then
      raise exception 'Media restriction requires approval privileges'
        using errcode = '42501';
    end if;
  end if;

  if (new.approved_by is distinct from old.approved_by
      or new.approved_at is distinct from old.approved_at) and not
      newsroom_private.has_staff_permission('media.approve',null,old.uploaded_by)
  then
    raise exception 'Media approval audit fields cannot be forged'
      using errcode = '42501';
  end if;
  if (new.trashed_at is distinct from old.trashed_at
      or new.archived_at is distinct from old.archived_at) and not
      newsroom_private.has_staff_permission('media.delete',null,old.uploaded_by)
  then
    raise exception 'Media deletion timestamps cannot be forged'
      using errcode = '42501';
  end if;
  return new;
end;
$fn$;

create trigger ct02g_media_asset_write_guard
before insert or update on public.media_assets for each row
execute function newsroom_private.guard_media_asset_write();
revoke all on function newsroom_private.guard_media_asset_write()
from public,anon,authenticated;

-- Storage backend still serves existing public URLs directly because the
-- 'media' bucket stays PUBLIC. SQL Storage policies govern list/upload/upsert/
-- delete, NOT public GET on a public bucket. Do not claim files are secret.
drop policy if exists media_bucket_read_staff on storage.objects;
drop policy if exists media_bucket_insert_staff on storage.objects;
drop policy if exists media_bucket_update_staff on storage.objects;
drop policy if exists media_bucket_delete_staff on storage.objects;

-- Owner IDs on all 22 imported objects are NULL; do not invent ownership.
-- Existing uploaded_by attribution in media_assets is the authoritative
-- ownership link, and the owner_id check is for NEW JWT-backed uploads.
create policy ct02g_storage_select_staff
on storage.objects for select to authenticated using (
  bucket_id = 'media' and (
    newsroom_private.has_staff_permission('media.view_all')
    or newsroom_private.has_staff_permission('media.edit_all')
    or (
      newsroom_private.has_staff_permission('media.upload')
      and owner_id = (select auth.uid())::text
    )
    or exists(
      select 1 from public.media_assets m
      where m.storage_path = name
        and m.uploaded_by = (select auth.uid())
        and newsroom_private.has_staff_permission('media.edit_own',null,m.uploaded_by)
    )
  )
);

create policy ct02g_storage_insert_staff
on storage.objects for insert to authenticated with check (
  bucket_id = 'media'
  and name like 'uploads/%'
  and owner_id = (select auth.uid())::text
  and newsroom_private.has_staff_permission('media.upload')
);

-- Upsert requires SELECT + UPDATE + INSERT as appropriate. Only editable
-- linked objects may be replaced; the caller cannot overwrite any arbitrary
-- old ownerless file merely by knowing its public URL/path.
create policy ct02g_storage_update_staff
on storage.objects for update to authenticated using (
  bucket_id = 'media' and exists(
    select 1 from public.media_assets m
    where m.storage_path = name and (
      newsroom_private.has_staff_permission('media.edit_all',null,m.uploaded_by)
      or (
        m.uploaded_by = (select auth.uid()) and
        newsroom_private.has_staff_permission('media.edit_own',null,m.uploaded_by)
      )
    )
  )
) with check (
  bucket_id = 'media' and exists(
    select 1 from public.media_assets m
    where m.storage_path = name and (
      newsroom_private.has_staff_permission('media.edit_all',null,m.uploaded_by)
      or (
        m.uploaded_by = (select auth.uid()) and
        newsroom_private.has_staff_permission('media.edit_own',null,m.uploaded_by)
      )
    )
  )
);

-- Deleting a catalogued image requires media.delete even if the uploader
-- owns the Storage object. For failed new uploads, a caller with media.upload
-- may clean up ONLY their unlinked own object.
create policy ct02g_storage_delete_staff
on storage.objects for delete to authenticated using (
  bucket_id = 'media' and (
    (
      exists (
        select 1 from public.media_assets m
        where m.storage_path = name
      ) and newsroom_private.has_staff_permission('media.delete')
    )
    or (
      owner_id = (select auth.uid())::text
      and newsroom_private.has_staff_permission('media.upload')
      and not exists(
        select 1 from public.media_assets m
        where m.storage_path = name
      )
    )
  )
);

-- WARNING: no UPDATE to storage.buckets.public. Existing public Storage URLs
-- still work; draft uploads in this PUBLIC bucket remain URL-accessible.
-- A separate, reviewed private-draft bucket + publish/promote workflow is
-- needed before claiming prepublication binary confidentiality.
commit;
